from pathlib import Path
import re

def norm(value):
    return re.sub(r'[^a-z0-9]+', ' ', str(value or '').casefold()).strip()

def uncertain(value):
    marker = r'\b(?:maybe|perhaps|possibly|might|uncertain|unknown|unconfirmed)\b'
    outcome = r'\b(?:needs?|needed|required|missing|invalid|wrong|mismatch|does not cover|doesn t cover|not valid)\b'
    for raw_clause in re.split(r'[\n\r]+|(?<=[.!?;])\s+', str(value or '')):
        clause = norm(raw_clause)
        if not clause or not re.search(outcome, clause):
            continue
        if '?' in raw_clause or re.search(marker, clause):
            return True
    return False

def alma_ok(value):
    text = norm(value)
    positive = re.search(r'\b(?:needs? (?:a )?certificate|(?:valid )?certificate(?: for s 31)? (?:is )?needed|(?:required )?certificate (?:is )?(?:missing|absent)|missing certificate|no (?:matching |valid )?certificate)\b', text)
    conflict = re.search(r'\bvalid certificate(?: for)? s 31\b(?! (?:is )?needed\b)|\b(?:does not|doesn t) need (?:a )?certificate\b', text)
    return bool(re.search(r'\bs 31\b', text) and positive and not conflict and not uncertain(value))

def dev_ok(value):
    text = norm(value)
    mismatch = re.search(r'\b(?:invalid|wrong session|mismatch|does not cover|doesn t cover|not valid for)\b', text)
    s20_valid_for_s28 = re.search(r'\bs 20\b(?: s)?(?: certificate)? (?:is |remains |considered )?valid (?:for )?s 28\b', text)
    existing_valid_s28 = re.search(r'\bvalid certificate(?: for)? s 28\b(?! (?:is )?needed\b)', text)
    return bool(re.search(r'\bs 28\b', text) and re.search(r'\bs 20\b', text) and mismatch and not s20_valid_for_s28 and not existing_valid_s28 and not uncertain(value))

try:
    raw = Path('/tmp/training/email_notes.md').read_text(encoding='utf-8').casefold()
    hits = [(match.start(), match.group(0)) for match in re.finditer(r'\b(?:alma reid|dev ban)\b', raw)]
    segments = []
    for index, (start, name) in enumerate(hits):
        if index and hits[index - 1][1] == name:
            continue
        end = len(raw)
        for next_start, next_name in hits[index + 1:]:
            if next_name != name:
                end = next_start
                break
        segments.append((name, raw[start:end]))
    alma_records = [segment for name, segment in segments if name == 'alma reid']
    dev_records = [segment for name, segment in segments if name == 'dev ban']
    ok = any(alma_ok(record) for record in alma_records) and any(dev_ok(record) for record in dev_records)
except Exception:
    ok = False
print('present' if ok else 'missing')
